-- Restore reviewed memberships and historical anchors only; retain unrelated later edits.
BEGIN;
SET LOCAL lock_timeout='5s';
LOCK TABLE public.stories,public.story_periods,public.story_entry_points,public.story_anchors,public.story_period_presentations IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.story_periods WHERE story_id=(SELECT id FROM public.stories WHERE title_fr='Époque contemporaine') AND period_id=(SELECT id FROM public.periods WHERE label_fr='Histoire contemporaine' AND start_date IS NOT DISTINCT FROM '1789' AND end_date IS NOT DISTINCT FROM 'TODAY')) THEN RAISE EXCEPTION 'A removed period was reattached. Re-audit before rollback.'; END IF;
 IF EXISTS(SELECT 1 FROM public.story_periods WHERE story_id=(SELECT id FROM public.stories WHERE title_fr='Moyen Âge') AND period_id=(SELECT id FROM public.periods WHERE label_fr='Moyen Âge' AND start_date IS NOT DISTINCT FROM '0476-09-04' AND end_date IS NOT DISTINCT FROM '1492-10-12')) THEN RAISE EXCEPTION 'A removed period was reattached. Re-audit before rollback.'; END IF;
 IF EXISTS(SELECT 1 FROM public.story_periods WHERE story_id=(SELECT id FROM public.stories WHERE title_fr='Antiquité et premières civilisations') AND period_id=(SELECT id FROM public.periods WHERE label_fr='Antiquité' AND start_date IS NOT DISTINCT FROM '3200 BCE' AND end_date IS NOT DISTINCT FROM '0476-09-04')) THEN RAISE EXCEPTION 'A removed period was reattached. Re-audit before rollback.'; END IF;
