 IF NOT EXISTS(SELECT 1 FROM public.story_periods WHERE story_id=(SELECT id FROM public.stories WHERE title_fr='Antiquité et premières civilisations') AND period_id=(SELECT id FROM public.periods WHERE label_fr='Antiquité égyptienne' AND start_date IS NOT DISTINCT FROM '3150 BCE' AND end_date IS NOT DISTINCT FROM '30 BCE') AND parent_period_id IS NULL) THEN RAISE EXCEPTION 'A child placement changed. Re-audit before rollback.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.story_periods WHERE story_id=(SELECT id FROM public.stories WHERE title_fr='Antiquité et premières civilisations') AND period_id=(SELECT id FROM public.periods WHERE label_fr='Antiquité romaine' AND start_date IS NOT DISTINCT FROM '753 BCE' AND end_date IS NOT DISTINCT FROM '0476-09-04') AND parent_period_id IS NULL) THEN RAISE EXCEPTION 'A child placement changed. Re-audit before rollback.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.story_periods WHERE story_id=(SELECT id FROM public.stories WHERE title_fr='Moyen Âge') AND period_id=(SELECT id FROM public.periods WHERE label_fr='Moyen Âge tardif' AND start_date IS NOT DISTINCT FROM '1301' AND end_date IS NOT DISTINCT FROM '1492-10-12') AND parent_period_id IS NULL) THEN RAISE EXCEPTION 'A child placement changed. Re-audit before rollback.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.story_periods WHERE story_id=(SELECT id FROM public.stories WHERE title_fr='Moyen Âge') AND period_id=(SELECT id FROM public.periods WHERE label_fr='Moyen Âge central' AND start_date IS NOT DISTINCT FROM '1000' AND end_date IS NOT DISTINCT FROM '1300') AND parent_period_id IS NULL) THEN RAISE EXCEPTION 'A child placement changed. Re-audit before rollback.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.story_entry_points WHERE source_story_id=(SELECT id FROM public.stories WHERE title_fr='Époque contemporaine') AND target_story_id=(SELECT id FROM public.stories WHERE title_fr='Conquête spatiale') AND period_id IS NULL AND event_id IS NULL) THEN RAISE EXCEPTION 'A root entry changed. Re-audit before rollback.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.story_entry_points WHERE source_story_id=(SELECT id FROM public.stories WHERE title_fr='Époque contemporaine') AND target_story_id=(SELECT id FROM public.stories WHERE title_fr='Guerres modernes') AND period_id IS NULL AND event_id IS NULL) THEN RAISE EXCEPTION 'A root entry changed. Re-audit before rollback.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.story_entry_points WHERE source_story_id=(SELECT id FROM public.stories WHERE title_fr='Époque contemporaine') AND target_story_id=(SELECT id FROM public.stories WHERE title_fr='Révolutions industrielles et énergie') AND period_id IS NULL AND event_id IS NULL) THEN RAISE EXCEPTION 'A root entry changed. Re-audit before rollback.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.story_entry_points WHERE source_story_id=(SELECT id FROM public.stories WHERE title_fr='Antiquité et premières civilisations') AND target_story_id=(SELECT id FROM public.stories WHERE title_fr='Mésopotamie') AND period_id IS NULL AND event_id IS NULL) THEN RAISE EXCEPTION 'A root entry changed. Re-audit before rollback.'; END IF;
