 IF NOT EXISTS(SELECT 1 FROM public.story_entry_points WHERE source_story_id=(SELECT id FROM public.stories WHERE title_fr='Époque contemporaine') AND target_story_id=(SELECT id FROM public.stories WHERE title_fr='Régimes politiques en France depuis l’Empire') AND period_id IS NULL AND event_id IS NULL) THEN RAISE EXCEPTION 'A root entry changed. Re-audit before rollback.'; END IF;
