UPDATE public.story_periods SET parent_period_id=(SELECT id FROM public.periods WHERE label_fr='Antiquité' AND start_date IS NOT DISTINCT FROM '3200 BCE' AND end_date IS NOT DISTINCT FROM '0476-09-04') WHERE story_id=(SELECT id FROM public.stories WHERE title_fr='Antiquité et premières civilisations') AND period_id=(SELECT id FROM public.periods WHERE label_fr='Antiquité romaine' AND start_date IS NOT DISTINCT FROM '753 BCE' AND end_date IS NOT DISTINCT FROM '0476-09-04');
UPDATE public.story_periods SET parent_period_id=(SELECT id FROM public.periods WHERE label_fr='Moyen Âge' AND start_date IS NOT DISTINCT FROM '0476-09-04' AND end_date IS NOT DISTINCT FROM '1492-10-12') WHERE story_id=(SELECT id FROM public.stories WHERE title_fr='Moyen Âge') AND period_id=(SELECT id FROM public.periods WHERE label_fr='Moyen Âge tardif' AND start_date IS NOT DISTINCT FROM '1301' AND end_date IS NOT DISTINCT FROM '1492-10-12');
UPDATE public.story_periods SET parent_period_id=(SELECT id FROM public.periods WHERE label_fr='Moyen Âge' AND start_date IS NOT DISTINCT FROM '0476-09-04' AND end_date IS NOT DISTINCT FROM '1492-10-12') WHERE story_id=(SELECT id FROM public.stories WHERE title_fr='Moyen Âge') AND period_id=(SELECT id FROM public.periods WHERE label_fr='Moyen Âge central' AND start_date IS NOT DISTINCT FROM '1000' AND end_date IS NOT DISTINCT FROM '1300');
